UPDATE ac SET LocalName = N'Trăn Miến Điện',
    ScriptText = N'Trăn Miến Điện là một trong những loài rắn lớn nhất thế giới, săn mồi bằng cách siết chặt.'
FROM AnimalContents ac JOIN Animals a ON a.Id = ac.AnimalId
WHERE a.Id = 8 AND a.ScientificName = N'Python bivittatus' AND ac.LanguageCode = 'vi';
